471→  function wireWidget(wid, cfg, API_BASE, SHOP) {
472→    var inp = document.getElementById(wid + "-inp");
473→    var btn = document.getElementById(wid + "-btn");
474→    var res = document.getElementById(wid + "-res");
475→    if (!inp || !btn || !res) return;
476→
477→    function normalizeZip(raw) {
478→      var z = raw.trim().toUpperCase();
479→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
480→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
481→      return z;
482→    }
483→
484→    function setBtnLoading(loading) {
485→      var iconEl = btn.querySelector('.zcc-btn-icon');
486→      var labelEl = btn.querySelector('.zcc-btn-label');
487→      btn.disabled = loading;
488→      if (loading) {
489→        if (iconEl) iconEl.innerHTML = ICONS.spinner;
490→        if (labelEl) labelEl.textContent = '\u2026';
491→      } else {
492→        if (iconEl) iconEl.innerHTML = ICONS.search;
493→        if (labelEl) labelEl.textContent = cfg.buttonText;
494→      }
495→    }
496→
497→    function checkZip() {
498→      var zip = normalizeZip(inp.value);
499→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
500→      if (!zip) { inp.focus(); return; }
501→
502→      setBtnLoading(true);
503→      res.innerHTML = "";
504→
505→      fetch(
506→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
507→          "&zip=" + encodeURIComponent(zip)
508→      )
509→        .then(function (r) { return r.json(); })
510→        .then(function (data) {
511→          setBtnLoading(false);
512→
513→          // Store validation result for cart page
514→          try {
515→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
516→            sessionStorage.setItem('zcc:zip', zip);
517→            sessionStorage.setItem('zcc:shop', SHOP);
518→            // Fire custom event for other scripts to listen to
519→            window.dispatchEvent(new CustomEvent('zcc:validated', {
520→              detail: { valid: data.allowed, zip: zip }
521→            }));
522→          } catch(e) { /* sessionStorage may be unavailable */ }
523→
524→          if (data.allowed) {
525→            var html = '<div class="zcc-result ok">' +
526→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
527→              '<div class="zcc-result-content">' +
528→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
529→            if (cfg.showEta && data.eta) {
530→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
531→            }
532→            if (cfg.showZone && data.zone) {
533→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
534→            }
535→            if (cfg.showDeliveryDays && data.daysOfWeek) {
536→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
537→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
538→            }
539→            if (cfg.showCutoffTime && data.cutoffTime) {
540→              var parts = data.cutoffTime.split(':');
541→              var hr = parseInt(parts[0], 10);
542→              var min = parts[1] || '00';
543→              var ampm = hr >= 12 ? 'PM' : 'AM';
544→              var hr12 = hr % 12 || 12;
545→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
546→            }
547→            if (data.codAvailable === true) {
548→              html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
549→            } else if (data.codAvailable === false) {
550→              html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
551→            }
552→            if (data.returnPolicy) {
553→              html += '<div class="zcc-return-policy">' + ICONS.refresh + '<span>' + esc(data.returnPolicy) + '</span></div>';
554→            }
555→            html += '</div></div>';
556→            res.innerHTML = html;
