563→              html +=
564→                '<div class="zcc-wl">' +
565→                '<button class="zcc-wl-toggle" id="' + wid + '-wl-toggle" type="button">' +
566→                ICONS.mail +
567→                ' Request delivery to your area</button>' +
568→                '<div id="' + wid + '-wl-form" style="display:none;margin-top:12px">' +
